const layout=(title,body)=>`<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><link rel="stylesheet" href="/static/style.css"><body><header class="header"><a class="brand" href="/"><span class="brandmark">✺</span><span>شهید اندرزگو</span></a><a class="navbutton" href="/events">رویدادها</a></header><main class="inner"><div class="eyebrow">مجموعه شهید اندرزگو</div><h1>${esc(title)}</h1>${body}</main><footer><a href="/">صفحه اصلی</a><a href="/admin">مدیریت</a></footer></body></html>`;
