const hex=a=>Array.from(new Uint8Array(a),x=>x.toString(16).padStart(2,'0')).join('');
async function digest(s){return hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))}
async function isAdmin(req,env){if(!env.ADMIN_PASSWORD)return false;const c=req.headers.get('Cookie')||'';const token=c.match(/(?:^|; )admin=([^;]+)/)?.[1];return token===await digest(env.ADMIN_PASSWORD+':andarzgoo-session-v1')}
function form(f,k){return String(f.get(k)||'').trim()}
const reply=(s,status=200)=>new Response(s,{status,headers:{'Content-Type':'text/plain; charset=utf-8'}});
export default {async fetch(req,env){try{
 const url=new URL(req.url),p=url.pathname,db=env.DB;
 if(p==='/static/style.css')return new Response(css,{headers:{'Content-Type':'text/css; charset=utf-8'}});
 if(p==='/static/hero.jpg')return new Response(Uint8Array.from(atob(img),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400'}});
 if(p==='/' && req.method==='GET')return new Response(pages['/'],{headers:{'Content-Type':'text/html; charset=utf-8'}});
 if(p==='/events' && req.method==='GET'){const {results}=await db.prepare('SELECT * FROM events WHERE active=1 ORDER BY id DESC').all();return html('رویدادها',results.map(e=>`<a class="listing" href="/event/${e.id}"><span>رایگان</span><h2>${esc(e.title)}</h2><p>${esc(e.location)}</p><b>مشاهده و ثبت‌نام ←</b></a>`).join('')||'<div class="empty">در حال حاضر رویدادی برای ثبت‌نام وجود ندارد.</div>')}
 if(/^\/event\/\d+$/.test(p)&&req.method==='GET'){let id=Number(p.split('/').pop());let e=await db.prepare('SELECT * FROM events WHERE id=? AND active=1').bind(id).first();if(!e)return html('رویداد پیدا نشد','',404);let {results}=await db.prepare('SELECT s.*,COALESCE(SUM(b.quantity),0) used FROM slots s LEFT JOIN bookings b ON s.id=b.slot_id WHERE s.event_id=? GROUP BY s.id ORDER BY s.date,s.start').bind(id).all();let opts=results.map(s=>`<option value="${s.id}" ${s.used>=s.capacity?'disabled':''}>${esc(s.date)} | ${esc(s.start)} تا ${esc(s.end)} | ${s.capacity-s.used} نفر باقی‌مانده</option>`).join('');return html(e.title,`<div class="event-hero" style="--theme:${esc(e.color)}"><p>${esc(e.description)}</p><p>${esc(e.location)} · رایگان</p></div><div class="booking"><div><h2>ثبت‌نام</h2><p>سانس و تعداد بلیت را انتخاب کنید.</p></div><form class="form" method="post" action="/book"><input type="hidden" name="event" value="${id}"><label>سانس<select name="slot" required>${opts}</select></label><label>نام و نام خانوادگی<input name="name" maxlength="100" required></label><label>شماره همراه<input name="phone" inputmode="tel" required></label><label>تعداد بلیت<input name="quantity" type="number" min="1" max="10" value="1" required></label><button class="btn dark" ${!results.length?'disabled':''}>ثبت رزرو</button></form></div>`)}
 if(p==='/book'&&req.method==='POST'){let f=await req.formData(),name=form(f,'name'),phone=form(f,'phone').replace(/[۰-۹٠-٩]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)>=0?'۰۱۲۳۴۵۶۷۸۹'.indexOf(c):'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[ -]/g,''),q=Number(form(f,'quantity')),slot=Number(form(f,'slot')),event=Number(form(f,'event'));if(!name||name.length>100||!/^09\d{9}$/.test(phone)||!Number.isInteger(q)||q<1||q>10||!Number.isInteger(slot)||!Number.isInteger(event))return html('اطلاعات نامعتبر','<p>لطفاً اطلاعات را بررسی کنید.</p>',400);let code=crypto.randomUUID().replaceAll('-','').slice(0,12).toUpperCase();let result=await db.prepare(`INSERT INTO bookings(slot_id,name,phone,quantity,code) SELECT s.id,?,?,?,? FROM slots s JOIN events e ON e.id=s.event_id WHERE s.id=? AND e.id=? AND e.active=1 AND s.capacity >= ? + (SELECT COALESCE(SUM(quantity),0) FROM bookings WHERE slot_id=s.id)`).bind(name,phone,q,code,slot,event,q).run();if(!result.meta.changes)return html('ظرفیت کافی نیست','<p>لطفاً سانس دیگری انتخاب کنید.</p>',409);return html('رزرو ثبت شد',`<div class="success"><p>کد پیگیری را نگه دارید.</p><strong dir="ltr">${code}</strong><p>تعداد بلیت: ${q}</p><a href="/events">بازگشت به رویدادها</a></div>`)}
 if(p==='/admin/login'&&req.method==='POST'){let f=await req.formData();let a=await digest(form(f,'password')),b=await digest(env.ADMIN_PASSWORD||crypto.randomUUID());if(a!==b)return html('ورود ناموفق','<p>رمز مدیریت نادرست است.</p><a href="/admin">بازگشت</a>',403);let token=await digest(env.ADMIN_PASSWORD+':andarzgoo-session-v1');return new Response(null,{status:303,headers:{Location:'/admin','Set-Cookie':`admin=${token}; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800`}})}
 if(p==='/admin'&&req.method==='GET'){if(!await isAdmin(req,env))return html('ورود مدیریت',env.ADMIN_PASSWORD?'<form method="post" action="/admin/login" class="form narrow"><label>رمز مدیریت<input name="password" type="password" required></label><button class="btn dark">ورود</button></form>':'<p>رمز مدیریت هنوز در Cloudflare تنظیم نشده است.</p>');let events=(await db.prepare('SELECT * FROM events ORDER BY id DESC').all()).results,slots=(await db.prepare('SELECT s.*,e.title,COALESCE(SUM(b.quantity),0) used FROM slots s JOIN events e ON e.id=s.event_id LEFT JOIN bookings b ON b.slot_id=s.id GROUP BY s.id ORDER BY s.id DESC').all()).results,bookings=(await db.prepare('SELECT b.*,e.title,s.date,s.start FROM bookings b JOIN slots s ON s.id=b.slot_id JOIN events e ON e.id=s.event_id ORDER BY b.id DESC LIMIT 100').all()).results;return html('مدیریت رویدادها',`<div class="admin-grid"><section class="panel"><h2>رویداد جدید</h2><form class="form" method="post" action="/admin/event"><label>عنوان<input name="title" required maxlength="120"></label><label>توضیحات<textarea name="description"></textarea></label><label>مکان<input name="location" required></label><label>رنگ<input type="color" name="color" value="#224b3d"></label><button class="btn dark">ساخت رویداد</button></form></section><section class="panel"><h2>افزودن سانس</h2><form class="form" method="post" action="/admin/slot"><label>رویداد<select name="event">${events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></label><label>تاریخ<input type="date" name="date" required></label><label>شروع<input type="time" name="start" required></label><label>پایان<input type="time" name="end" required></label><label>ظرفیت<input type="number" name="capacity" min="1" max="100000" required></label><button class="btn dark">افزودن سانس</button></form></section><section class="panel"><h2>رویدادها و سانس‌ها</h2>${events.map(e=>`<p>${esc(e.title)} — ${e.active?'فعال':'غیرفعال'} <form class="inline" method="post" action="/admin/toggle"><input type="hidden" name="id" value="${e.id}"><button>تغییر وضعیت</button></form></p>`).join('')}${slots.map(s=>`<p>${esc(s.title)} · ${esc(s.date)} ${esc(s.start)} تا ${esc(s.end)} · ${s.used}/${s.capacity}</p>`).join('')}</section></div><section class="panel"><h2>ثبت‌نام‌ها</h2><div class="table"><table><tr><th>نام</th><th>شماره</th><th>رویداد</th><th>سانس</th><th>تعداد</th><th>کد</th></tr>${bookings.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.phone)}</td><td>${esc(b.title)}</td><td>${esc(b.date)} ${esc(b.start)}</td><td>${b.quantity}</td><td>${esc(b.code)}</td></tr>`).join('')}</table></div></section>`)}
 if(p.startsWith('/admin/')&&req.method==='POST'){if(!await isAdmin(req,env))return reply('Forbidden',403);if(req.headers.get('Origin')!==url.origin)return reply('Forbidden',403);let f=await req.formData();if(p==='/admin/event'){let t=form(f,'title'),d=form(f,'description'),l=form(f,'location'),c=form(f,'color');if(!t||t.length>120||d.length>4000||!l||l.length>300||!/^#[0-9a-f]{6}$/i.test(c))return reply('Invalid',400);await db.prepare('INSERT INTO events(title,description,location,color) VALUES(?,?,?,?)').bind(t,d,l,c).run()}else if(p==='/admin/slot'){let id=Number(form(f,'event')),date=form(f,'date'),start=form(f,'start'),end=form(f,'end'),cap=Number(form(f,'capacity'));if(!Number.isInteger(id)||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(start)||!/^\d{2}:\d{2}$/.test(end)||end<=start||!Number.isInteger(cap)||cap<1||cap>100000)return reply('Invalid',400);await db.prepare('INSERT INTO slots(event_id,date,start,end,capacity) SELECT id,?,?,?,? FROM events WHERE id=?').bind(date,start,end,cap,id).run()}else if(p==='/admin/toggle'){await db.prepare('UPDATE events SET active=1-active WHERE id=?').bind(Number(form(f,'id'))).run()}else return reply('Not found',404);return go('/admin')}
 return html('صفحه پیدا نشد','',404)
 }catch(e){console.error('request failed',e.message);return reply('خطای سرور',500)}}};
